var ENGINE = _global.getCurrentEngine();
var start_x = 460;
var start_y = 230;
var SHELL = _global.getCurrentShell();
var language;
var localized_frame = 1;
if(SHELL.getLocalizedFrame != undefined)
{
   localized_frame = SHELL.getLocalizedFrame();
}
switch(localized_frame)
{
   case 1:
      language = "en";
      break;
   case 2:
      language = "pt";
      break;
   case 3:
      language = "fr";
      break;
   case 4:
      language = "es";
      break;
   case 5:
      language = "de";
      break;
   default:
      language = "en";
}
doorwall_mc.gotoAndStop(language);
triggers_mc.shiphold_mc.triggerFunction = function()
{
   ENGINE.sendJoinRoom("shiphold",610,390);
};
triggers_mc.beach_mc.triggerFunction = function()
{
   ENGINE.sendJoinRoom("beach",356,222);
};
background_mc.flag_mc.flag_btn.useHandCursor = false;
doorwall_mc.shiphold_btn.onRelease = function()
{
   ENGINE.sendPlayerMove(300,242);
};
foreground_mc.ladder_btn.onRelease = function()
{
   ENGINE.sendJoinRoom("shipnest",356,222);
};
triggers_mc._visible = false;
block_mc._visible = false;
var wem = new com.clubpenguin.world.rooms.weathereffects.WeatherEffectsManager(SHELL,background_mc);
wem.setupFireAnimationHeight(55);
wem.setupRainAnimationHeight(85);
wem.setupSnowAnimationHeight(85);
wem.setupRainAnimationSpeed(0.5);
wem.setupSnowAnimationSpeed(1);
wem.setupRainDelayTime(2);
wem.setupRainDelayTime(2);
wem.startWeatherEffectCheck();
